reference.code:
def turns_to_target(start, gain, target, maximum_turns):
    turns = 0
    value = start
    while value < target and turns < maximum_turns:
        value = value + gain
        turns = turns + 1
    if value >= target:
        return turns
    return -1

print(turns_to_target(0, 3, 8, 3))

