reference.code:
count = 0
total = 0
while True:
    command = input().strip().lower()
    if command == "quit":
        print("Finished.")
        break
    elif command == "add":
        total = total + int(input())
        count = count + 1
    elif command == "report":
        print(f"Sessions: {count} | Total: {total} min")
    else:
        print("Unknown command")
